window.BANK=window.BANK||{};window.BANK["8370"]={"n":"套卷19","qs":[{"i":"166352","t":"单选","q":"对于青年来说，决定人生价值的最大砝码是","o":{"A":"A.青年的理想信念","B":"B.青年的道德水准","C":"C.青年的本领才干","D":"D.青年的担当"},"a":"D","j":"新时代呼唤担当民族复兴大任的时代新人(绪论)【简析】青春至美是担当，青年的担当是决定人生价值的最大砝码。有担当的青年是影响时代发展进程的重要力量。新时代的中国，更需要使命在肩、奋斗有我的精神。我们越是接近中华民族的伟大复兴，越是需要付出更为艰巨、更为艰苦的努力。大学生的担当精神体现为奉献祖国、服务人民、尽心尽力、勇于担责。D正确，ABC不符合题意。","k":"考点1 新时代呼唤担当民族复兴大任的时代新人","kid":"564","r":12,"tot":21},{"i":"166353","t":"单选","q":"认识和处理人生问题的重要着眼点和出发点是","o":{"A":"A.理想与现实的关系","B":"B.个人与集体的关系","C":"C.个人与社会的关系","D":"D.个人与国家的关系"},"a":"C","j":"个人与社会的辩证关系(第一章)【简析】人是社会的人，社会是人们相互交往的产物，是人类生活的共同体，人生的内容与社会活动密不可分。个人与社会的关系问题是认识和处理人生问题的重要着眼点和出发点。C正确，ABD不符合题意。","k":"考点3 人生观是对人生的总看法","kid":"92","r":12,"tot":15},{"i":"166354","t":"单选","q":"评价人生价值的根本尺度是","o":{"A":"A.看一个人是否具有自强不息的精神","B":"B.看一个人的实践活动是否符合社会发展规律，是否促进历史进步","C":"C.看一个人是否既注重社会贡献，又注重自身完善","D":"D.看一个人是否不断增强实现人生价值的能力"},"a":"B","j":"<p>人生价值的评价(第一章)</p>\n<p>【简析】评价人生价值的根本尺度，是看一个人的实践活动是否符合社会发展的客观规律，是否促进了历史的进步。B正确，ACD不符合题意。</p>\n<p>【笔记】</p>\n<p><img src=\"assets/images/2EFAF824E9A2A9028FB8D8C272560511.png\" /></p>","k":"考点4 正确的人生观","kid":"93","r":11,"tot":12},{"i":"166355","t":"单选","q":"人的精神世界的核心是","o":{"A":"A.人生观","B":"B.世界观","C":"C.理想信念","D":"D.价值观"},"a":"C","j":"<p>理想信念是精神之&ldquo;钙&rdquo;(第二章)</p>\n<p>【简析】理想信念是人的精神世界的核心，是人精神上的&ldquo;钙&rdquo;。没有理想信念，理想信念不坚定，精神上就会&ldquo;缺钙&rdquo;,就会得&ldquo;软骨病&rdquo;。C正确，ABD不符合题意。</p>\n<p>【笔记】</p>\n<p>关于理想信念的六个论断：</p>\n<p>1.理想信念是人的精神世界的核心。</p>\n<p>2.理想信念是人生发展的内在动力。</p>\n<p>3.理想信念是人的思想和行为的定向器。</p>\n<p>4.理想信念是一个人在精神生活领域&ldquo;安身立命&rdquo;的根本。</p>\n<p>5.理想信念是衡量一个人精神境界高下的重要标尺。</p>\n<p>6.理想信念决定我们的方向和立场，决定我们的精神状态和实际行动。</p>","k":"考点9 理想信念的作用","kid":"371","r":9,"tot":20},{"i":"166356","t":"单选","q":"个人理想和社会理想关系的实质是","o":{"A":"A.个人与社会的关系在价值层面的反映","B":"B.个人利益与社会利益的关系","C":"C.个人与社会的关系在理想层面的反映","D":"D.个人实践与社会实践的关系"},"a":"C","j":"<p>坚持个人理想与社会理想的有机结合(第二章)【简析】个人理想与社会理想的关系实质上是个人与社会的关系在理想层面的反映。个人与社会有机地联系在一起，二者相互依存、相互制约、共同发展。同样，社会理想与个人理想也不是彼此孤立的，它们之间相互联系、相互影响、相互制约。C正确，ABD不符合题意。</p>","k":"考点11 坚持个人理想与社会理想的有机结合","kid":"373","r":4,"tot":12},{"i":"166357","t":"单选","q":"检验一个人对祖国忠诚程度的试金石是","o":{"A":"A.骨肉同胞之爱","B":"B.灿烂文化之爱","C":"C.大好河山之爱","D":"D.民族利益之爱"},"a":"A","j":"弘扬以爱国主义为核心的民族精神(第三章)【简析】骨肉同胞之爱反映了对民族利益共同体的自觉认同，是检验一个人对祖国忠诚程度的试金石。A正确，BCD不符合题意。","k":"考点16 实现中国梦必须弘扬中国精神","kid":"380","r":16,"tot":18},{"i":"166358","t":"单选","q":"文化软实力的灵魂是","o":{"A":"A.理想信念","B":"B.政治制度","C":"C.核心价值观","D":"D.经济发展"},"a":"C","j":"当代中国发展进步的精神指引(第四章)【简析】核心价值观是文化软实力的灵魂、文化软实力建设的重点。这是决定文化性质和方向的最深层次要素。一个国家的文化软实力，从根本上说，取决于其核心价值观的生命力、凝聚力、感召力。C正确，ABD不符合题意。","k":"考点21 当代中国发展进步的精神指引","kid":"387","r":14,"tot":17},{"i":"166359","t":"单选","q":"恩格斯指出：“人们自觉地或不自觉地，归根到底总是从他们阶级地位所依据的实际关系中——从他们进行生产和交换的经济关系中，获得自己的伦理观念。”这表明道德的产生、发展和变化，归根结底根源于","o":{"A":"A.统治阶级利益","B":"B.社会上层建筑","C":"C.社会意识形态","D":"D.社会经济关系"},"a":"D","j":"道德的本质(第五章)【简析】道德是反映社会经济关系的特殊意识形态。道德的产生、发展和变化，归根结底源于社会经济关系。D正确，ABC不符合题意。","k":"考点24 坚持马克思主义道德观","kid":"392","r":12,"tot":16},{"i":"166360","t":"单选","q":"社会主义道德区别和优越于其他社会形态道德的显著标志是","o":{"A":"A.以中华优秀传统文化为核心","B":"B.以为人民服务为核心","C":"C.以集体主义为原则","D":"D.以创新发展人类优秀道德资源为目标"},"a":"B","j":"坚持以为人民服务为核心(第五章)【简析】为人民服务作为社会主义道德的核心，是社会主义道德区别和优越于其他社会形态道德的显著标志。当代青年践行为人民服务，就是要弘扬为人民服务的精神，尊重人、理解人、关心人，为人民、为社会、为国家多做好事、多作贡献。B正确，ACD不符合题意。","k":"考点25 坚持以为人民服务为核心","kid":"393","r":11,"tot":14},{"i":"166361","t":"单选","q":"在我国，长期以来，调节国家利益、社会整体利益和个人利益关系的基本原则是","o":{"A":"A.先公后私","B":"B.集体主义","C":"C.遵纪守法","D":"D.奉献社会"},"a":"B","j":"坚持以集体主义为原则(第五章)【简析】社会主义道德的原则是集体主义。在我国，国家利益、社会整体利益和个人利益根本上的一致性，使得集体主义应当而且能够在全社会范围内贯彻实施。长期以来，集体主义已经成为调节国家利益、社会整体利益和个人利益关系的基本原则。B正确，ACD不符合题意。","k":"考点26 坚持以集体主义为原则","kid":"394","r":11,"tot":18},{"i":"166362","t":"单选","q":"革命道德的灵魂是","o":{"A":"A.全心全意为人民服务","B":"B.修身自律，保持节操","C":"C.坚持社会主义和共产主义的理想信念","D":"D.树立社会新风，建立新型人际关系"},"a":"C","j":"中国革命道德的主要内容(第五章)【简析】坚持社会主义和共产主义理想信念是革命道德的灵魂。无数革命先烈，正是为了实现这样一个崇高的理想，毫不犹豫地献出了自己的生命。C正确，ABD不符合题意。强干扰项是A。全心全意为人民服务作为贯穿中国革命道德始终的一根红线，是中国共产党在中国革命实践中的一个伟大创造，对中国的革命、建设、改革事业产生了极其重大的推动作用。","k":"考点28 发扬中国革命道德","kid":"396","r":9,"tot":17},{"i":"166363","t":"单选","q":"清代有个叫叶存仁的官员，从政30余年，甘于淡泊，从不苟取。一次离任时，僚属们临别馈赠礼品，为避人耳目，特地夜里送来。叶存仁见状将礼品原封退回，并赋诗一首相赠：“月白风清夜半时，扁舟相送故迟迟。感君情重还君赠，不畏人知畏己知。”从道德修养方法的角度看，这个故事体现的道德修养方法是","o":{"A":"A.省察克治的方法","B":"B.积善成德的方法","C":"C.学思并重的方法","D":"D.慎独自律的方法"},"a":"D","j":"<p>道德修养重在践行(第五章)</p>\n<p>【简析】慎独自律的方法即在无人知晓、没有外在监督的情况下，坚守自己的道德信念，自觉按道德要求行事，不因为无人监督而恣意妄为。题干给出的故事体现了慎独自律的方法。D正确，ABC不符合题意。</p>\n<p>【笔记】</p>\n<p><img src=\"assets/images/063D90E7F2CB51323E826501651AD5FB.png\" /></p>","k":"考点32 锤炼个人品德","kid":"400","r":12,"tot":15},{"i":"166364","t":"单选","q":"法律运行的起始性和关键性环节是","o":{"A":"A.法律制定","B":"B.法律遵守","C":"C.法律执行","D":"D.法律适用"},"a":"A","j":"我国社会主义法律的运行(第六章)【简析】法律制定是指有立法权的国家机关，依照法定职权和程序制定规范性法律文件的活动，是法律运行的起始性和关键性环节。A正确，BCD不符合题意。强干扰项是B。法律遵守是法律实施和实现的基本途径。","k":"考点35 我国社会主义法律的运行","kid":"407","r":18,"tot":21},{"i":"166365","t":"单选","q":"推进法治建设的目标是","o":{"A":"A.法治国家","B":"B.法治素养","C":"C.法治政府","D":"D.法治社会"},"a":"A","j":"<p>建设法治中国(第六章)</p>\n<p>【简析】法治国家、法治政府、法治社会相辅相成，法治国家是法治建设的目标，法治政府是建设法治国家的重点，法治社会是构筑法治国家的基础。A正确，BCD不符合题意。</p>\n<p>【笔记】</p>\n<p><img src=\"data:image/png;base64,\" alt=\"\" /></p>","k":"考点38 建设法治中国","kid":"410","r":11,"tot":15},{"i":"166366","t":"单选","q":"科学立法是","o":{"A":"A.全面依法治国的前提","B":"B.全面依法治国的关键","C":"C.全面依法治国的重点","D":"D.全面依法治国的基础"},"a":"A","j":"<p>坚持全面推进科学立法、严格执法、公正司法、全民守法(第六章)</p>\n<p>【简析】科学立法是全面依法治国的前提，严格执法是全面依法治国的关键，公正司法是全面依法治国的重点，全民守法是全面依法治国的基础。全面依法治国，必须从立法、执法、司法、守法四个方面统筹推进。A正确，BCD不符合题意。故本题选A。</p>\n<p>【笔记】</p>\n<p><img src=\"assets/images/7E1A81509A3D15B31ED4853ACA1FCBD1.png\" /></p>","k":"考点36 全面依法治国的根本遵循——习近平法治思想","kid":"408","r":13,"tot":17},{"i":"166367","t":"单选","q":"40多年普法历程启示我们，法律的权威源自","o":{"A":"A.国家强制力的有效实施与保障","B":"B.立法机关的民主程序与崇高地位","C":"C.人民的内心拥护和真诚信仰","D":"D.杰出领袖人物的智慧与权威"},"a":"C","j":"尊重法律权威(第六章)【简析】40多年普法历程启示我们：法律的权威源自人民的内心拥护和真诚信仰。C正确，ABD不符合题意。强干扰项是A。法律规范的实施是由国家强制力来保障的。","k":"考点44 不断提升法治素养","kid":"416","r":9,"tot":15},{"i":"166368","t":"多选","q":"下列关于个人利益和社会利益的关系表述正确的是","o":{"A":"A.在任何社会中，个人利益和社会利益在根本上都是一致的","B":"B.社会利益就是个人利益的简单相加","C":"C.社会利益体现了作为社会成员的个人的根本利益和长远利益","D":"D.社会利益是个人利益得以实现的前提和基础，保障着个人利益的实现"},"a":"CD","j":"个人与社会的辩证关系(第一章)【简析】社会利益不是个人利益的简单相加，而是所有人利益的有机统一。B错误。社会利益体现了作为社会成员的个人的根本利益和长远利益，是个人利益得以实现的前提和基础，同时它也保障着个人利益的实现。CD正确。在社会主义社会，个人利益和社会利益在根本上才是一致的。A错误，故本题选CD。","k":"考点3 人生观是对人生的总看法","kid":"92","r":14,"tot":19},{"i":"166369","t":"多选","q":"青春奋斗，强国有我。把青春华章谱写在祖国大地上，以“青春之我”为“青春之国家”而奋斗。一滴水，只有融入江海，才不会干涸；一个人的青春，也只有同人民一起奋斗才能方向不偏、同民族一起前进才能焕发光彩、同国家一起梦想才能前程远大。这说明","o":{"A":"A.人生的社会价值可以替代人生的自我价值","B":"B.个体的人生活动必然地包含着满足社会需要的价值属性","C":"C.人生社会价值的实现是个体自我完善、全面发展的保障","D":"D.个体通过努力提高自我价值的过程，也是其创造社会价值的过程"},"a":"BCD","j":"人生的自我价值和社会价值(第一章)【简析】个体的人生活动不仅具有满足自我需要的价值属性，还必然地包含着满足社会需要的价值属性。个体通过努力提高自我价值的过程，也是其创造社会价值的过程。BD正确。人生的社会价值是社会存在和发展的重要条件，人生社会价值的实现是个体自我完善、全面发展的保障。C正确。人生价值内在地包含了人生的自我价值和社会价值两个方面。人生的自我价值和社会价值，既相互区别，又密切联系、相互依存。A错误。故本题选BCD。","k":"考点3 人生观是对人生的总看法","kid":"92","r":9,"tot":12},{"i":"166370","t":"多选","q":"倡导革命乐观主义精神，是因为","o":{"A":"A.苦与乐在一定条件下可以相互转化","B":"B.真正的快乐只能由奋斗的艰苦转化而来","C":"C.不经历人生的苦难，也可以享受到人生的乐趣","D":"D.苦与乐是对立统一的"},"a":"ABD","j":"正确看待苦与乐(第一章)【简析】苦与乐既对立又统一，在一定条件下还可以相互转化。AD正确。奋斗是艰辛的，艰难困苦、玉汝于成。真正的快乐只能由奋斗的艰苦转化而来。不经历风雨怎能见彩虹，不经历人生的苦难，怎能享受到人生的乐趣。B正确，C错误。故本题选ABD。","k":"考点5 创造有意义的人生","kid":"360","r":9,"tot":15},{"i":"166371","t":"多选","q":"下列关于信念表述正确的是","o":{"A":"A.信念具有执着性，一旦形成，就不会改变","B":"B.信念具有支撑性，是一个人经受实践考验而能始终坚守理想的精神力量","C":"C.信念具有多样性，同一个人在社会实践中会形成不同类型和层次的信念","D":"D.信念具有偶然性，没有科学和非科学之分"},"a":"BC","j":"信念的内涵与特征(第二章)【简析】信念具有支撑性。信念是一个人经受实践考验而能始终坚守理想的精神力量。B正确。信念具有多样性。不同的人由于社会环境、思想观念、利益需要、人生经历和性格特征等方面的差异，会形成不同的信念，同时一个人在社会实践中会形成不同类型和层次的信念。C正确。信念具有执着性。信念一旦形成，就不会轻易改变。“不会轻易改变”不等于“不会改变”。A错误。信仰有盲目和科学之分。盲目的信仰就是对虚幻的世界、不切实际的观念、荒谬的理论等对象的迷信和狂热崇拜，科学的信仰则来自人们对自然界和人类社会发展规律的正确认识。D错误。故本题选BC。","k":"考点7 信念的内涵与特征","kid":"369","r":9,"tot":14},{"i":"166372","t":"多选","q":"理想信念是","o":{"A":"A.人生发展的内在动力","B":"B.一个人在精神生活领域“安身立命”的根本","C":"C.衡量一个人精神境界高下的重要标尺","D":"D.民族精神的核心"},"a":"ABC","j":"理想信念是精神之“钙”(第二章)【简析】理想信念是人的精神世界的核心，是人精神上的“钙”。理想指引方向，信念决定成败。理想信念是人生发展的内在动力。A正确。理想信念提供精神支柱。理想信念是一个人在精神生活领域“安身立命”的根本。B正确。理想信念提高精神境界。理想信念是衡量一个人精神境界高下的重要标尺。C正确。爱国主义是民族精神的核心。D不符合题意。故本题选ABC。","k":"考点9 理想信念的作用","kid":"371","r":11,"tot":13},{"i":"166373","t":"多选","q":"历史川流不息，精神代代相传。百年来，在革命、建设、改革各个历史时期，一代又一代中国共产党人顽强拼搏、不懈奋斗，涌现了一大批视死如归的革命烈士、一大批顽强奋斗的英雄人物、一大批忘我奉献的先进模范，形成了井冈山精神、长征精神、遵义会议精神、延安精神、西柏坡精神、红岩精神、抗美援朝精神、“两弹一星”精神、特区精神、抗洪精神、抗震救灾精神、抗疫精神、脱贫攻坚精神等伟大精神，构筑起中国共产党人的精神谱系。这一精神谱系","o":{"A":"A.集中体现了党的坚定信念、根本宗旨、优良作风","B":"B.凝聚着中国共产党人艰苦奋斗、牺牲奉献、开拓进取的伟大品格","C":"C.深深融入我们党、国家、民族、人民的血脉之中","D":"D.极大丰富了中国精神的内涵"},"a":"ABCD","j":"中国共产党是中国精神的忠实继承者和坚定弘扬者(第三章)【简析】中国共产党人的精神谱系，是中国共产党领导人民在实践中集体奋斗和共同创造的，集中体现了党的坚定信念、根本宗旨、优良作风，凝聚着中国共产党人艰苦奋斗、牺牲奉献、开拓进取的伟大品格，深深融入我们党、国家、民族、人民的血脉之中，极大丰富了中国精神的内涵，鼓舞和激励中国人民攻坚克难，不断从胜利走向新的胜利。ABCD正确。","k":"考点15 中国共产党是中国精神的忠实继承者和坚定弘扬者","kid":"379","r":9,"tot":11},{"i":"166374","t":"多选","q":"在现阶段，爱国主义主要表现为在中国共产党领导下，献身于","o":{"A":"A.建设新时代中国特色社会主义伟大事业","B":"B.实现中华民族伟大复兴的中国梦的实践","C":"C.促进祖国统一大业","D":"D.救亡图存、建设社会主义新中国"},"a":"ABC","j":"坚持爱国爱党爱社会主义相统一(第三章)【简析】在现阶段，爱国主义主要表现为在中国共产党领导下，献身于建设新时代中国特色社会主义伟大事业，献身于实现中华民族伟大复兴的中国梦的实践，献身于促进祖国统一大业。ABC正确。救亡图存、建设社会主义新中国是新民主主义革命时期爱国主义的主要表现。D不符合题意。","k":"考点17 大力弘扬新时代爱国主义","kid":"381","r":10,"tot":14},{"i":"166375","t":"多选","q":"青年是国家的未来、民族的希望，青年的价值观决定着未来整个社会的价值取向。新时代，要坚持以社会主义核心价值观滋养青年，培养担当民族复兴大任的时代新人，这是因为培育和践行社会主义核心价值观","o":{"A":"A.能有效整合我国社会意识、凝聚社会价值共识","B":"B.是实现中华民族伟大复兴的价值支撑","C":"C.是中国特色社会主义的铸魂工程","D":"D.是解决和化解社会矛盾、聚合磅礴之力的重大举措"},"a":"ABCD","j":"当代中国发展进步的精神指引(第四章)【简析】培育和践行社会主义核心价值观，是有效整合我国社会意识、凝聚社会价值共识、解决和化解社会矛盾、聚合磅礴之力的重大举措，是保证我国经济社会沿着正确的方向发展、实现中华民族伟大复兴的价值支撑。ABD正确。在全社会大力弘扬社会主义核心价值观，明确中国特色社会主义事业到底追求什么、反对什么,要朝着什么方向走、不能朝什么方向走，坚守我们的价值观立场，坚定中国特色社会主义的道路自信、理论自信、制度自信和文化自信，为社会的有序运行、良性发展提供明确价值准则，保证中国特色社会主义事业始终沿着正确方向前进，是中国特色社会主义的铸魂工程。C正确。故本题选ABCD。","k":"考点21 当代中国发展进步的精神指引","kid":"387","r":10,"tot":11},{"i":"166376","t":"多选","q":"社会主义核心价值观具有超越以往一切核心价值观的先进性，这种先进性表现在","o":{"A":"A.彰显超越时空的普世价值","B":"B.扎根中华优秀传统文化土壤","C":"C.体现社会主义的本质属性","D":"D.吸收借鉴一切人类优秀文化的先进价值"},"a":"BCD","j":"反映人类社会发展进步的价值观念(第四章)【简析】社会主义核心价值观具有超越以往一切社会核心价值观的先进性，它集中体现了社会主义的本质属性，扎根于中华优秀传统文化的土壤，吸收借鉴了一切人类优秀文化的先进价值，是反映人类社会发展进步的价值理念。BCD正确。西方所谓的“普世价值”从抽象的“人性论”出发，将人看作无差别的价值符号。事实上根本不存在抽象的人性，也没有放之四海而皆准的价值观及其相应的制度。A错误。故本题选BCD。","k":"考点22 社会主义核心价值观的显著特征","kid":"388","r":8,"tot":10},{"i":"166377","t":"多选","q":"道德","o":{"A":"A.对社会发展具有能动的反作用","B":"B.能够孤立地调节社会关系","C":"C.是一种对社会发展具有决定作用的精神力量","D":"D.立足现实而追求理想，并以理想来改造和提升现实"},"a":"AD","j":"道德的作用(第五章)【简析】作为社会意识的道德一经产生，便有相对独立性。这种相对独立性既表现为道德的历史继承性，也表现为道德对社会发展具有能动的反作用。A正确。道德是一种实践精神。道德立足现实而追求理想，并以理想来改造和提升现实。D正确。在社会生活中，道德调节并不是孤立进行的，而是和其他社会调节手段密切配合、共同发挥调节效果。B错误。对社会发展具有决定作用的是物质生产方式。C错误。故本题选AD。","k":"考点24 坚持马克思主义道德观","kid":"392","r":10,"tot":11},{"i":"166378","t":"多选","q":"市场经济之所以需要集体主义，是因为集体主义","o":{"A":"A.有助于克服市场自身的弱点和消极方面","B":"B.有助于形成追求高尚、激励先进的良好社会风气","C":"C.保证公民在道德上做到无私奉献、一心为公","D":"D.保证社会主义市场经济的有序健康发展"},"a":"ABD","j":"坚持以集体主义为原则(第五章)【简析】社会主义市场经济之所以需要集体主义，是因为其有助于克服市场自身的弱点和消极方面，有助于形成追求高尚、激励先进的良好社会风气，保证社会主义市场经济的有序健康发展。ABD正确。“无私奉献、一心为公”是集体主义的最高层次，是优秀共产党员、先进分子应努力达到的道德目标。C错误。故本题选ABD。","k":"考点26 坚持以集体主义为原则","kid":"394","r":7,"tot":9},{"i":"166379","t":"多选","q":"有序的公共生活是","o":{"A":"A.社会生产活动的重要基础","B":"B.区分社会制度性质的首要条件","C":"C.提高社会成员生活质量的基本保障","D":"D.社会文明的重要标志"},"a":"ACD","j":"遵守社会公德(第五章)【简析】有序的公共生活是社会生产活动的重要基础，是提高社会成员生活质量的基本保障，更是社会文明的重要标志。ACD正确。区分社会制度性质的首要条件是占统治地位的生产关系的性质。B不符合题意。","k":"考点29 遵守社会公德","kid":"397","r":8,"tot":10},{"i":"166380","t":"多选","q":"在对待中国传统道德问题上，存在“虚无论”和“复古论”的观点，以下对这两种观点的评述，理解正确的有","o":{"A":"A.“虚无论”主张以传统道德代替社会主义道德","B":"B.“复古论”主张形成以中国传统文化为主体的道德体系","C":"C.两者都割断了道德的历史与发展的关系","D":"D.“虚无论”和“复古论”都不利于社会的发展和道德进步"},"a":"BCD","j":"中华传统美德的创造性转化和创新性发展(第五章)【简析】在对待传统道德的问题上，要反对两种错误思潮。一种是“复古论”,认为道德建设的最终目标就是要恢复中国“固有文化”,形成以中国传统文化为主体的道德体系；另一种是“虚无论”,认为中国传统道德从整体上来说在今天已经失去了价值和意义，必须从整体上予以全盘否定。这两种观点都是错误的，割断了道德的历史与发展的关系，都不利于社会的发展和道德进步。BCD正确，A错误。强干扰项是A。“主张以传统道德代替社会主义道德”属于“复古论”观点。","k":"考点28 发扬中国革命道德","kid":"396","r":6,"tot":11},{"i":"166381","t":"多选","q":"法律制定","o":{"A":"A.是国家对权利和义务进行的权威性分配","B":"B.遵守公正、公平、公开原则","C":"C.是法律运行的起始性和关键性环节","D":"D.遵循中立性、参与性、公开性原则"},"a":"ABC","j":"我国社会主义法律的运行(第六章)【简析】法律制定是国家对权利和义务，即社会利益和负担进行的权威性分配。法律制定是指有立法权的国家机关，依照法定职权和程序制定规范性法律文件的活动，是法律运行的起始性和关键性环节。我国立法贯彻公正、公平、公开原则，坚持科学立法、民主立法、依法立法，表达人民的共同意志和诉求。ABC正确。程序的正当，表现在程序的合法性、中立性、参与性、公开性、时限性等方面。D不符合题意。","k":"考点35 我国社会主义法律的运行","kid":"407","r":5,"tot":10},{"i":"166382","t":"多选","q":"走中国特色社会主义法治道路是","o":{"A":"A.历史的必然结论","B":"B.由我国社会主义国家性质所决定的","C":"C.关起门来搞法治的必然结果","D":"D.立足我国基本国情的必然选择"},"a":"ABD","j":"坚持走中国特色社会主义法治道路(第六章)【简析】走中国特色社会主义法治道路，是历史的必然结论，是由我国社会主义国家性质所决定的，是立足我国基本国情的必然选择。ABD正确。从国情实际出发，不等于关起门来搞法治，我们要坚持以我为主、为我所用，认真鉴别、合理吸收世界上优秀的法治文明成果。C错误。故本题选ABD。","k":"考点37 坚持走中国特色社会主义法治道路","kid":"409","r":10,"tot":11},{"i":"166383","t":"多选","q":"以下关于法律权利的表述，正确的有","o":{"A":"A.不能脱离一个国家或地区的经济社会发展阶段和水平空谈权利及其实现","B":"B.同样一种权利，在不同的社会制度下和不同的国家法律中表现形式是相同的","C":"C.由国家强制力保障其实现是法律权利区别于其他权利的根本所在","D":"D.国家机关行使权力不得任性，公民个人行使法律权利也不得任性"},"a":"ACD","j":"法律权利与法律义务(第六章)【简析】法律权利具有以下四个方面的特征。一是法律权利的内容、种类和实现程度受社会物质生活条件的制约。不能脱离一个国家或地区的经济社会发展阶段和水平而空谈权利及其实现。二是法律权利的内容、分配和实现方式因社会制度和国家法律的不同而存在差异。同样一种权利，在不同的社会制度下和不同的国家法律中表现形式有所不同。三是法律权利不仅由法律规定或认可，而且受法律维护或保障，具有不可侵犯性。由国家强制力保障其实现，这是法律权利区别于其他权利的根本所在。四是法律权利必须依法行使，不能不择手段地行使法律权利。国家机关行使权力不得任性，公民个人行使法律权利也不得任性。ACD正确，B错误。故本题选ACD。","k":"考点43 依法行使权利与履行义务","kid":"415","r":12,"tot":13},{"i":"166384","t":"多选","q":"权力制约表现为","o":{"A":"A.国家机关必须严格依照法律规定的权限行使职权，视情况行使法律未授予的权力","B":"B.当发生了属于其职权范围内的事项时，国家机关必须履行相应的管理职责","C":"C.国家权力的运行和行使必须接受各种形式的监督，让人民监督权力，让权力在阳光下运行","D":"D.国家工作人员违法行使权力必须受到法律的追究和制裁"},"a":"BCD","j":"法治思维的基本内容(第六章)【简析】权力制约包括权力由法定、有权必有责、用权受监督、违法受追究四项要求。权力由法定，即法无授权不可为，是指国家机关的职权必须来自法律明确的授予。国家机关必须严格依照法律规定的权限行使职权，不得行使法律未授予的权力。A错误。有权必有责，是指国家机关在获得权力的同时必须承担相应的职责和责任。当发生了属于其职权范围内的事项时，国家机关必须履行相应的管理职责。B正确。用权受监督，是指国家权力的运行和行使必须接受各种形式的监督，让人民监督权力，让权力在阳光下运行。C正确。违法受追究，是指国家工作人员违法行使权力必须受到法律的追究和制裁。D正确。故本题选BCD。","k":"考点42 培养社会主义法治思维","kid":"414","r":7,"tot":12}]};
